import React, { useState } from "react";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import "./styles.css";
import logo from "./assets/logo.jpeg"; // coloque seu logo aqui

const logoBase64 =
  "data:image/jpeg;base64,";

export function App() {
  const [cliente, setCliente] = useState("");
  const [itens, setItens] = useState([]);
  const [descricao, setDescricao] = useState("");
  const [quantidade, setQuantidade] = useState(1);
  const [valor, setValor] = useState("");
  const [editIndex, setEditIndex] = useState(null);
  const [gerandoPDF, setGerandoPDF] = useState(false);

  const dataAtual = new Date().toLocaleDateString("pt-BR");

  const adicionarOuEditarItem = () => {
    if (!descricao || !valor) return;

    const novoItem = {
      descricao,
      quantidade: parseInt(quantidade),
      valor: parseFloat(valor),
    };

    if (editIndex !== null) {
      const novosItens = [...itens];
      novosItens[editIndex] = novoItem;
      setItens(novosItens);
      setEditIndex(null);
    } else {
      setItens([...itens, novoItem]);
    }

    setDescricao("");
    setQuantidade(1);
    setValor("");
  };

  const editarItem = (index) => {
    const item = itens[index];
    setDescricao(item.descricao);
    setQuantidade(item.quantidade);
    setValor(item.valor);
    setEditIndex(index);
  };

  const removerItem = (index) => {
    const novosItens = itens.filter((_, i) => i !== index);
    setItens(novosItens);
  };

  const total = itens.reduce(
    (acc, item) => acc + item.quantidade * item.valor,
    0
  );

  const gerarPDF = () => {
    const pdf = new jsPDF("p", "mm", "a4");

    let y = 10;

    // LOGO
    try {
      pdf.addImage(logoBase64, "PNG", 150, 10, 40, 40);
    } catch (e) {
      console.log("Erro ao carregar logo");
    }

    // EMPRESA
    pdf.setFontSize(16);
    pdf.text("Upgrade Audio Car", 10, y);
    y += 8;

    pdf.setFontSize(10);
    pdf.text("Rua Valter da Silva n 111 - Por do Sol", 10, y);
    y += 5;
    pdf.text("Quatá - SP", 10, y);
    y += 5;
    pdf.text("Telefone: (18) 99642-5357", 10, y);
    y += 15;

    // DATA E CLIENTE
    pdf.text(`Data: ${dataAtual}`, 10, y);
    y += 5;
    pdf.text(`Cliente: ${cliente}`, 10, y);
    y += 10;

    // CABEÇALHO TABELA
    pdf.setFontSize(11);
    pdf.text("Descrição", 10, y);
    pdf.text("Qtd", 110, y);
    pdf.text("Valor", 130, y);
    pdf.text("Total", 160, y);

    y += 5;
    pdf.line(10, y, 200, y);
    y += 5;

    // ITENS
    itens.forEach((item) => {
      if (y > 270) {
        pdf.addPage();
        y = 10;
      }

      pdf.text(item.descricao, 10, y);
      pdf.text(String(item.quantidade), 110, y);
      pdf.text(`R$ ${item.valor.toFixed(2)}`, 130, y);
      pdf.text(`R$ ${(item.quantidade * item.valor).toFixed(2)}`, 160, y);

      y += 7;
    });

    y += 10;

    // TOTAL
    pdf.setFontSize(14);
    pdf.text(`Total: R$ ${total.toFixed(2)}`, 140, y);

    pdf.save("orcamento.pdf");
  };

  return (
    <div className="container">
      <h1>Gerador de Orçamento</h1>

      <input
        placeholder="Nome do Cliente"
        value={cliente}
        onChange={(e) => setCliente(e.target.value)}
      />

      <input
        placeholder="Descrição"
        value={descricao}
        onChange={(e) => setDescricao(e.target.value)}
      />

      <input
        type="number"
        placeholder="Qtd"
        value={quantidade}
        onChange={(e) => setQuantidade(e.target.value)}
      />

      <input
        type="number"
        placeholder="Valor"
        value={valor}
        onChange={(e) => setValor(e.target.value)}
      />

      <button onClick={adicionarOuEditarItem}>
        {editIndex !== null ? "Salvar" : "Adicionar"}
      </button>

      <button className="btn-pdf" onClick={gerarPDF}>
        Gerar PDF
      </button>

      {/* ORÇAMENTO */}
      <div id="orcamento" className="orcamento">
        <div className="header">
          <div>
            <h2>Upgrade Audio Car</h2>
            <p>Rua Valter da Silva n 111 - Por do Sol</p>
            <p>Quatá - SP</p>
            <p>Telefone: (18) 99642-5357</p>
          </div>

          <img src={logo} alt="logo" />
        </div>

        <hr />

        <p>
          <strong>Data:</strong> {dataAtual}
        </p>
        <p>
          <strong>Cliente:</strong> {cliente}
        </p>

        <table>
          <thead>
            <tr>
              <th>Descrição</th>
              <th>Qtd</th>
              <th>Valor</th>
              <th>Total</th>
              {!gerandoPDF && <th>Ações</th>}
            </tr>
          </thead>

          <tbody>
            {itens.map((item, index) => (
              <tr key={index}>
                <td>{item.descricao}</td>
                <td>{item.quantidade}</td>
                <td>R$ {item.valor.toFixed(2)}</td>
                <td>R$ {(item.quantidade * item.valor).toFixed(2)}</td>

                {!gerandoPDF && (
                  <td>
                    <button onClick={() => editarItem(index)}>Editar</button>
                    <button onClick={() => removerItem(index)}>Remover</button>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>

        <h3 className="total">Total: R$ {total.toFixed(2)}</h3>
      </div>
    </div>
  );
}
